'use strict';
// Passwords and derived keys are never persisted. IndexedDB stores ciphertext and salt/IV only.
const guardRegistry=new Map(), unlockedGuards=new Map();
const bytesTo64=a=>btoa(String.fromCharCode(...new Uint8Array(a)));
const from64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const textBytes=s=>new TextEncoder().encode(s);
const guardAAD=id=>textBytes('luutru:guard:v1:'+id);
const fileAAD=(id,guard)=>textBytes('luutru:file:v1:'+id+':'+guard);
function ownGuard(f){return f&&guardRegistry.get(f.id)}
function ancestors(f){const result=[],seen=new Set();let p=f&&file(f.parent);while(p&&!seen.has(p.id)){seen.add(p.id);result.unshift(p);p=file(p.parent)}return result}
function guardsFor(f){if(!f)return[];return [...new Set([...ancestors(f).map(x=>x.id),...(f.cryptoGuards||[]),f.id])].map(id=>guardRegistry.get(id)).filter(Boolean)}
function locked(f){return guardsFor(f).some(g=>!unlockedGuards.has(g.id))}
function hiddenByLock(f){return ancestors(f).some(p=>locked(p))}
function lockBadge(f){return guardsFor(f).length?`<span class="badge ${locked(f)?'purple':'green'}">${icon('lock')} ${locked(f)?'Có mật khẩu':'Đã mở khóa'}</span>`:''}
function protectionButton(f){return `<button class="btn btn-light py-2" onclick="protectionModal('${f.id}')" title="Bảo vệ bằng mật khẩu">${icon('lock')}${ownGuard(f)?'Bảo mật':'Mã hóa'}</button>`}
async function deriveFileKey(password,salt){const material=await crypto.subtle.importKey('raw',textBytes(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:from64(salt),iterations:210000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function makeGuard(id,name,password){const salt=bytesTo64(crypto.getRandomValues(new Uint8Array(16))),iv=crypto.getRandomValues(new Uint8Array(12)),key=await deriveFileKey(password,salt);const check=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:guardAAD(id)},key,textBytes('luutru-password-check-v1'));return{guard:{id,name,salt,iv:bytesTo64(iv),check:bytesTo64(check)},key}}
async function verifyGuard(g,password){const key=await deriveFileKey(password,g.salt);await crypto.subtle.decrypt({name:'AES-GCM',iv:from64(g.iv),additionalData:guardAAD(g.id)},key,from64(g.check));return key}
async function encryptLayer(record,id,g,key){const iv=crypto.getRandomValues(new Uint8Array(12));const data=record.encrypted?record.data:await record.arrayBuffer();return{encrypted:1,type:record.type||'',layers:[...(record.layers||[]),{guard:g.id,iv:bytesTo64(iv)}],data:await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:fileAAD(id,g.id)},key,data)}}
async function encryptUpload(blob,id,folder){let record=blob;for(const g of guardsFor(folder)){const key=unlockedGuards.get(g.id);if(!key)throw Error('Hãy mở khóa thư mục trước khi tải lên.');record=await encryptLayer(record,id,g,key)}return record}
async function decryptRecord(record,id){if(!record?.encrypted)return record;let data=record.data;for(const layer of [...record.layers].reverse()){const key=unlockedGuards.get(layer.guard);if(!key)throw Error('Cần nhập mật khẩu để mở tệp.');data=await crypto.subtle.decrypt({name:'AES-GCM',iv:from64(layer.iv),additionalData:fileAAD(id,layer.guard)},key,data)}return new Blob([data],{type:record.type})}
async function readUnlockedBlob(id){const record=await blobs('get',id);return record?decryptRecord(record,id):null}
async function initializeProtection(){const d=await blobDB();const keys=await new Promise((resolve,reject)=>{const r=d.transaction('files').objectStore('files').getAllKeys();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});guardRegistry.clear();for(const k of keys.filter(k=>String(k).startsWith('guard:'))){const g=await blobs('get',k);guardRegistry.set(g.id,g);for(const id of g.members||[]){const f=file(id);if(f)f.cryptoGuards=[...new Set([...(f.cryptoGuards||[]),g.id])]}}}
function requireUnlocked(f,done){if(!accessible(f)){toast('Tài liệu không tồn tại hoặc bạn không có quyền truy cập.');return}const guard=guardsFor(f).find(g=>!unlockedGuards.has(g.id));if(!guard){done();return}if(!crypto.subtle)return toast('Mở khóa cần HTTPS hoặc localhost. Hãy chạy theo hướng dẫn trong ZIP.');modal('Nhập mật khẩu để mở',`<div class="lock-intro">${icon('lock')}<h3>${esc(guard.name)}</h3><p class="small muted">${f.id===guard.id?'Tài liệu này':'Nội dung này'} được bảo vệ bằng mật khẩu. Mở khóa có hiệu lực trong phiên hiện tại.</p></div><form>${field('Mật khẩu tệp / thư mục','unlock','','password','required autocomplete="off"')}<p id="unlock-error" class="error" role="alert"></p><button class="btn btn-primary w-100">${icon('lock')}Mở khóa</button></form>`,async(fd,form)=>{const button=form.querySelector('button');button.disabled=true;try{const key=await verifyGuard(guard,fd.get('unlock'));unlockedGuards.set(guard.id,key);closeModal();requireUnlocked(f,done)}catch{$('#unlock-error').textContent='Mật khẩu không đúng. Vui lòng thử lại.';button.disabled=false}})}
function relockAll(){unlockedGuards.clear();closeModal();parent=null;query='';typeFilter='';render();toast('Đã khóa lại các tệp và thư mục trong phiên này.')}
function protectionModal(id){const f=file(id);if(!f||f.owner!==current()?.id)return toast('Chỉ chủ sở hữu được đặt mật khẩu.');if(ownGuard(f)){modal('Bảo vệ bằng mật khẩu',`<div class="lock-intro">${icon('lock')}<h3>${esc(f.name)}</h3>${lockBadge(f)}</div><p class="small muted">Mật khẩu được yêu cầu khi mở nội dung, kể cả với người được chia sẻ. Tệp tải lên được lưu dưới dạng mã hóa; tên và thông tin tệp vẫn hiển thị.</p><button class="btn btn-primary w-100" onclick="closeModal();openFile('${id}')">Mở ${f.type==='folder'?'thư mục':'tệp'}</button><button class="btn btn-light w-100 mt-2" onclick="relockAll()">Khóa lại ngay</button>`);return}if(!crypto.subtle)return toast('Mã hóa cần HTTPS hoặc localhost. Hãy chạy theo hướng dẫn trong ZIP.');requireUnlocked(f,()=>modal('Mã hóa '+(f.type==='folder'?'thư mục':'tệp'),`<div class="d-flex align-items-center gap-3 mb-3">${fIcon(f)}<b>${esc(f.name)}</b></div><p class="small muted">${f.type==='folder'?'Mật khẩu bảo vệ cả thư mục con và các tệp bên trong, kể cả tệp tải lên sau này.':'Nhập mật khẩu khi xem hoặc tải xuống tệp này.'}</p><form>${field('Mật khẩu bảo vệ','password','','password','required minlength="8" autocomplete="new-password"')}${field('Nhập lại mật khẩu','confirm','','password','required minlength="8" autocomplete="new-password"')}<p class="small muted">Ít nhất 8 ký tự. Hãy ghi nhớ mật khẩu; bản mẫu không có chức năng khôi phục mật khẩu mã hóa.</p><p id="protect-status" class="small" role="status"></p><button class="btn btn-primary w-100">${icon('lock')}Đặt mật khẩu và mã hóa</button></form>`,async(fd,form)=>{if(fd.get('password')!==fd.get('confirm'))return toast('Mật khẩu nhập lại không khớp.');const b=form.querySelector('button');b.disabled=true;$('#protect-status').textContent='Đang mã hóa. Vui lòng giữ trang mở…';try{await protectItem(f,fd.get('password'));closeModal();render();toast('Đã mã hóa và khóa nội dung. Nhập mật khẩu khi mở.')}catch(err){$('#protect-status').textContent='Không thể mã hóa: '+(err.message||'bộ nhớ không đủ hoặc bị chặn')+'. Dữ liệu gốc được giữ lại.';b.disabled=false}}))}
async function protectItem(f,password){const {guard,key}=await makeGuard(f.id,f.name,password),members=[f,...(f.type==='folder'?descendants(f.id):[])];guard.members=members.map(x=>x.id);const staged=[];try{for(const item of members.filter(x=>x.local)){const record=await blobs('get',item.id);if(!record)throw Error('Thiếu nội dung tệp '+item.name);const encrypted=await encryptLayer(record,item.id,guard,key);const temp='stage:'+uid();await blobs('put',temp,encrypted);staged.push({id:item.id,temp})}const d=await blobDB();await new Promise((resolve,reject)=>{const tx=d.transaction('files','readwrite'),s=tx.objectStore('files');for(const item of staged){const r=s.get(item.temp);r.onsuccess=()=>{if(!r.result){tx.abort();return}s.put(r.result,item.id);s.delete(item.temp)}}s.put(guard,'guard:'+guard.id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Giao dịch đã hủy'))});guardRegistry.set(guard.id,guard);members.forEach(x=>x.cryptoGuards=[...new Set([...(x.cryptoGuards||[]),guard.id])]);unlockedGuards.delete(guard.id);save()}catch(e){await Promise.all(staged.map(x=>blobs('delete',x.temp).catch(()=>{})));throw e}}
function breadcrumbHtml(p,shared){const chain=[...ancestors(p),p];return`<nav class="folder-breadcrumb" aria-label="Đường dẫn thư mục"><button class="breadcrumb-button" onclick="go('${shared?'shared':'files'}')">${icon('folder')}${shared?'Chia sẻ với tôi':'Tài liệu của tôi'}</button>${chain.map((f,i)=>`<span class="muted">/</span>${i===chain.length-1?`<span aria-current="page">${esc(f.name)}</span>`:`<button class="breadcrumb-button" onclick="openFile('${f.id}')">${esc(f.name)}</button>`}`).join('')}</nav>`}
function folderCards(folders,u,shared){return`<div class="sectionhead"><h2 class="mb-0">${parent?'Thư mục con':'Thư mục'+(shared?' được chia sẻ':'')}</h2><span class="small muted">${folders.length} thư mục</span></div><div class="foldergrid">${folders.map(f=>`<div class="foldercard"><button class="folder-open" onclick="openFile('${f.id}')">${fIcon(f)}<h3>${esc(f.name)}</h3><div class="small muted">${locked(f)?'Nhập mật khẩu để xem nội dung':db.files.filter(x=>x.parent===f.id&&active(x)).length+' mục trực tiếp'}</div><div class="mt-2">${lockBadge(f)}</div></button>${f.owner===u.id?`<div class="folder-tools">${protectionButton(f)}<button class="iconbtn" aria-label="Tùy chọn ${esc(f.name)}" onclick="folderDetails('${f.id}')">${icon('edit')}</button></div>`:'<div class="px-3 pb-3"><span class="badge blue">Được chia sẻ</span></div>'}</div>`).join('')}</div>`}
function addNestedDemo(){if(db.nestedDemoV2)return;const root=file('d1');if(root&&!root.deleted&&!ownGuard(root)){const entries=[['demo-sub-1','Thiết kế giao diện','folder','d1',0],['demo-sub-2','Bản bàn giao','folder','demo-sub-1',0],['demo-sub-file','Mô tả màn hình.pdf','document','demo-sub-1',1200000],['demo-deep-file','Checklist bàn giao.xlsx','document','demo-sub-2',450000]];entries.forEach(([id,name,type,parent,bytes])=>{if(!file(id))db.files.push({id,name,type,parent,bytes,owner:root.owner,shared:[],created:Date.now(),deleted:null})})}db.nestedDemoV2=true;save()}
